"""枚举每种形状实际可能抽出的口味组合，独立验证最坏情况答案。"""
import hashlib,itertools,json,random
from pathlib import Path
root=Path.cwd();e=next(e for e in json.loads((root/'collab/gmyhf-pending-batch10-review.json').read_text())['entries'] if e['global_number']==31239)
source=e['authored_reference']['source'];assert hashlib.sha256(source.encode()).hexdigest()==e['authored_reference']['sha256']
ns={};exec(source.split('import sys\nsys.stdout.write')[0],ns)
def brute(rows):
 n=len(rows);bad=set()
 for draws in itertools.product(*(range(v+1) for r in rows for v in r)):
  if not any(draws[3*i] and draws[3*j+1] for i in range(n) for j in range(n) if i!=j):
   bad.add(tuple(sum(draws[3*i:3*i+3]) for i in range(n)))
 return min((sum(c) for c in itertools.product(*(range(sum(r)+1) for r in rows)) if c not in bad),default=-1)
patterns=list(itertools.product((0,1),repeat=3));cases=[]
for n in (2,3):
 for rows in itertools.product(patterns,repeat=n):
  if any(map(any,rows)):cases.append(rows)
rng=random.Random(31239)
for _ in range(80):
 rows=[tuple(rng.randrange(3) for _ in range(3)) for _ in range(2)]
 if any(map(any,rows)):cases.append(rows)
checks=[]
for rows in cases:
 expected=brute(rows);actual=ns['single_pair'](rows);assert actual==expected,(rows,expected,actual)
 checks.append({'rows':rows,'answer':actual})
s=Path(__file__).read_text();report={'global_number':31239,'reference_sha256':e['authored_reference']['sha256'],'cases':len(checks),'all_matched':True,'checks':checks,'procedure_source':s,'procedure_sha256':hashlib.sha256(s.encode()).hexdigest()}
